	this.frame_13 = function() {
		this.stop(); // Hentikan layar di frame intro
		var root = this;
		root.stop();
		
		if (window.mainkanVO) window.mainkanVO("vo_login");
		
		// Amankan status login agar bisa di-reset jika kembali ke frame ini
		window.sedangLogin = false;
		
		window.hapusInputLogin = function() {
		    ["inputNama", "inputKelas"].forEach(function(id) {
		        var el = document.getElementById(id);
		        if (el) el.remove();
		    });
		};
		window.hapusInputLogin();
		
		if (root.txt_pesan) root.txt_pesan.text = "";
		
		// Posisi input mengikuti posisi & skala canvas
		function buatInput(id, placeholder, x, y) {
		    var c = document.getElementById("canvas");
		    var r = c.getBoundingClientRect();
		    var s = r.width / 800;
		    var el = document.createElement("input");
		    
		el.type = "text";
		el.id = id;
		el.placeholder = placeholder;
		el.style.position = "absolute";
		el.style.left = (r.left + window.pageXOffset + x * s) + "px";
		el.style.top = (r.top + window.pageYOffset + y * s) + "px";
		el.style.width = (179 * s) + "px";
		el.style.height = (40 * s) + "px";
		el.style.fontSize = (20 * s) + "px";
		el.style.fontWeight = "bold";
		el.style.color = "#FFFFFF";
		el.style.backgroundColor = "transparent"; // Mengubah fill menjadi transparan
		el.style.border = "none";                 // Menghilangkan garis tepi kotak
		el.style.padding = "0px 10px";
		el.style.outline = "none";
		el.style.zIndex = "999";
		    
		    el.addEventListener("keydown", function(e) {
		        if (e.key === "Enter") prosesLogin();
		    });
		    
		    document.body.appendChild(el);
		    return el;
		}
		
		function prosesLogin() {
		    if (window.sedangLogin) return;
		    
		    var eNama = document.getElementById("inputNama");
		    var eKelas = document.getElementById("inputKelas");
		    if (!eNama || !eKelas) return;
		
		    var nama = eNama.value.trim();
		    var kelas = eKelas.value.trim();
		
		    if (nama === "" || kelas === "") {
		        if (root.txt_pesan) {
		            root.txt_pesan.text = "Silahkan isi kolom yang kosong!";
		            root.txt_pesan.color = "#FF0000";
		        }
		        return;
		    }
		
		    window.sedangLogin = true;
		    if (root.txt_pesan) {
		        root.txt_pesan.text = "SELAMAT KAMU BERHASIL LOGIN!";
		        root.txt_pesan.color = "#FFFFFF";
		    }
		    
		    window.namaPemain = nama;
		    window.kelasPemain = kelas;
		    window.hapusInputLogin();
		
		    // Jeda 1 detik lalu pindah ke home
		    setTimeout(function() { 
		        root.gotoAndStop("home"); 
		    }, 1000);
		}
		
		buatInput("inputNama", "Ketik Nama...", 369, 138);
		buatInput("inputKelas", "Ketik Kelas...", 370, 196);
		
		// LOGIKA MASTER: Gunakan standar native .on("click") 
		if (root.btn_login) {
		    // Hapus listener lama untuk mencegah bentrok/double trigger jika frame di-load ulang
		    root.btn_login.removeAllEventListeners("click");
		    root.btn_login.on("click", prosesLogin);
		}
	}
	this.frame_14 = function() {
		this.stop();
		var root = this;
		var menu = this.mc_menu;
		
		
		// Reset MovieClip beserta seluruh isi di dalamnya ke frame awal
		function resetMC(mc) {
		    if (mc.mode === createjs.MovieClip.INDEPENDENT) mc.gotoAndPlay(0);
		    (mc.children || []).forEach(function (c) {
		        if (c instanceof createjs.MovieClip) resetMC(c);
		    });
		}
		
		
		
		if (window.nyalakanBGM) window.nyalakanBGM();      // musik kembali menyala setelah keluar dari game
		if (window.mainkanVO) window.mainkanVO("vo_home"); // vo_home ada di Library tapi tidak dipanggil di mana pun
		
		// 1. OBAT ANTI BERKEDIP: Paksa tutup popup di detik ke-0 saat masuk frame ini
		if (window.tutupPengaturan) window.tutupPengaturan();
		if (window.tutupExit) window.tutupExit();
		
		// Pemasang tombol. Suara klik TIDAK diputar di sini: sudah ditangani SENSOR KLIK di Layer_4 frame 1
		// (kalau diputar lagi di sini, bunyinya jadi dobel).
		function klik(tombol, tugas) {
		    if (tombol) {
		        tombol.removeAllEventListeners("click");
		        tombol.cursor = "pointer";
		        tombol.on("click", function() {
		            tugas();
		        });
		    }
		}
		function pindah(namaFrame) {
		    return function() { 
		        if (window.currentSound) window.currentSound.stop();
		        root.gotoAndStop(namaFrame); 
		    };
		}
		
		// 2. KENDALI TOMBOL DALAM MENU (Kamar mc_menu)
		if (menu) {
		    if (menu.txt_sapa) menu.txt_sapa.text = (window.namaPemain || "Pemain") + " kelas " + (window.kelasPemain || "Umum");
		    klik(menu.btn_petunjuk,  pindah("petunjuk"));
		    klik(menu.btn_materi,    pindah("materi"));
		    klik(menu.btn_profile,   pindah("profil"));
		    klik(menu.btn_mulaiGame, pindah("pilMap"));
		    
		    // Tombol logout di dalam menu bisa diatur untuk membuka popup exit
		    klik(menu.btn_logout, function() {
		        if (window.bukaExit) window.bukaExit();
		    });
		}
		
		// 3. KENDALI POP-UP PENGATURAN
		klik(root.btn_pengaturan, function() {
		    if (window.statusPengaturanBuka) window.tutupPengaturan(); else window.bukaPengaturan();
		});
		klik(root.btn_ok,   function() { window.tutupPengaturan(); });
		klik(root.btn_up,   function() { window.ubahVolume(0.1); });
		klik(root.btn_down, function() { window.ubahVolume(-0.1); });
		klik(root.btn_on,   function() { createjs.Sound.muted = true;  window.updateTampilanMusik(); });
		klik(root.btn_off,  function() { createjs.Sound.muted = false; window.updateTampilanMusik(); });
		
		// 4. KENDALI POP-UP EXIT UTAMA
		klik(root.btn_exit, function() {
		    if (window.statusExitBuka) window.tutupExit(); else window.bukaExit();
		});
		klik(root.btn_tidak, function() { window.tutupExit(); });
		klik(root.btn_iya, function() {
		    window.open('', '_self', '');
		    window.close();
		    setTimeout(function() { location.href = "about:blank"; }, 300);
		});
	}
