		    notif.visible = true;
		    notif.x = posX;
		    notif.y = posY;
		    notif.scaleX = notif.scaleY = skalaAsli;
		    notif.alpha = 0;
		
		    if (notif.parent) notif.parent.setChildIndex(notif, notif.parent.numChildren - 1);
		
