	this.frame_29 = function() {
		var root = this;
		root.stop();
		
		// ==========================================
		// 1. AMBIL DATA DARI SESI GAME YANG BARU KALAH
		// ==========================================
		var skorAkhir = window.skorPemain || 0;
		var sisaDetik = (window.sisaWaktu !== undefined) ? window.sisaWaktu : 0;
		var totalWaktu = window.WAKTU_AWAL || 180;
		
		// ==========================================
		// 2. HELPER
		// ==========================================
		function pasang(tombol, tugas) {
		    if (!tombol) return;
		    tombol.removeAllEventListeners("click");
		    tombol.cursor = "pointer";
		    tombol.on("click", tugas);
		}
		
		// Cari objek teks dari daftar objek yang SEDANG tampil di frame ini (tidak peduli huruf besar/kecil)
		function ambilObjek(nama) {
		    var kecil = nama.toLowerCase();
		    for (var i = root.children.length - 1; i >= 0; i--) {
		        var c = root.children[i];
		        if (c && c.name && String(c.name).toLowerCase() === kecil) return c;
		    }
		    return root[nama] || null;
		}
		
		// Isi teks + pastikan terlihat dan berada di lapisan paling atas
		function isiTeks(nama, isi, warna) {
		    var t = ambilObjek(nama);
		    if (!t) {
		        var daftar = [];
		        for (var i = 0; i < root.children.length; i++) {
		            if (root.children[i].name) daftar.push(root.children[i].name);
		        }
		        console.warn("[GAMEOVER] objek '" + nama + "' TIDAK ditemukan di frame ini. Objek bernama yang ada:", daftar);
		        return null;
		    }
		    t.text = isi;
		    t.visible = true;
		    t.alpha = 1;
		    if (warna) t.color = warna;
		    root.addChild(t);
		    return t;
		}
		
		function formatMMSS(detik) {
		    detik = Math.max(0, Math.floor(detik));
		    var m = Math.floor(detik / 60);
		    var s = detik % 60;
		    var strM = (m < 10) ? "0" + m : "" + m;
		    var strS = (s < 10) ? "0" + s : "" + s;
		    return strM + ":" + strS;
		}
		
		// ==========================================
		// 3. SUARA: snd_gameover -> lalu vo_mengulang (otomatis stop saat popup ditutup)
		// ==========================================
		window.hentikanSuaraGameOver = function() {
		    window.popupGameOverAktif = false;
		    if (window.timerVoGameOver) { clearTimeout(window.timerVoGameOver); window.timerVoGameOver = null; }
		    if (window.suaraGameOver) { window.suaraGameOver.stop(); window.suaraGameOver = null; }
		    if (window.voGameOver) { window.voGameOver.stop(); window.voGameOver = null; }
		    if (window.currentSound) window.currentSound.stop();
		};
		
		window.mainkanSuaraGameOver = function() {
		    // bersihkan sisa suara sebelumnya
		    if (window.timerVoGameOver) { clearTimeout(window.timerVoGameOver); window.timerVoGameOver = null; }
		    if (window.currentSound) window.currentSound.stop();
		    window.popupGameOverAktif = true;
		
		    var voSudahMain = false;
		    function mainkanVoMengulang() {
		        if (voSudahMain || !window.popupGameOverAktif) return;
		        voSudahMain = true;
		        if (window.timerVoGameOver) { clearTimeout(window.timerVoGameOver); window.timerVoGameOver = null; }
		        window.voGameOver = createjs.Sound.play("vo_mengulang");
		        window.currentSound = window.voGameOver;
		    }
		
		    var sfx = createjs.Sound.play("snd_gameover");
		    window.suaraGameOver = sfx;
		    window.currentSound = sfx;
		
		    sfx.on("complete", mainkanVoMengulang);
		    sfx.on("failed", mainkanVoMengulang);
		
		    if (sfx.playState === createjs.Sound.PLAY_FAILED) {
		        mainkanVoMengulang();
		    } else {
		        // cadangan bila event "complete" tidak terpanggil
		        var jeda = (sfx.duration > 0) ? sfx.duration : 3000;
		        window.timerVoGameOver = setTimeout(mainkanVoMengulang, jeda + 300);
		    }
		};
		
		// ==========================================
		// 4. RESET TOTAL MEMORI GAME
		// ==========================================
		window.resetGameOver = function() {
		    // A. Suara popup berhenti
		    window.hentikanSuaraGameOver();
		
		    // B. Hentikan semua timer & loop game yang mungkin masih hidup
		    if (window.gameTimer) clearInterval(window.gameTimer);
		    if (window.timerMulai) clearInterval(window.timerMulai);
		    if (window.timerRespawn) clearTimeout(window.timerRespawn);
		    if (window.jalankanGameFisika) createjs.Ticker.removeEventListener("tick", window.jalankanGameFisika);
		
		    // C. Reset data permainan
		    window.skorPemain = 0;
		    window.sisaWaktu = window.WAKTU_AWAL || 180;
		    window.nyawaPemain = 3;
		    window.soalTerjawab = [false, false, false, false, false];
		    window.posisiKotakTerakhir = null;
		
		    // D. Reset status game agar inGame1 melakukan setup ulang dari titik start
		    //    (posisiStartAsliX/Y & worldXAsli sengaja DIBIARKAN supaya start asli dipulihkan)
		    window.posisiAwalDiset = false;
		    window.kameraSudahSetup = false;
		    window.sedangMati = false;
		    window.gameBerhenti = false;
		    window.sedangLompat = false;
		    window.kecepatanY = 0;
		    window.voIngameSudahJalan = false;
		    window.tombolKiri = false;
		    window.tombolKanan = false;
		    window.tombolAtas = false;
		};
		
		// ==========================================
		// 5. TAMPILKAN DATA POP-UP
		// ==========================================
		var WARNA_TXT_GAGAL = null;   // contoh: "#FF3B30". Isi bila teks terlalu gelap/sama dengan warna latar
		
		var waktuTerpakai = totalWaktu - sisaDetik;
		if (waktuTerpakai < 0) waktuTerpakai = 0;
		
		var tGagal = isiTeks("txt_gagal", "KAMU GAGAL", WARNA_TXT_GAGAL);
		isiTeks("txt_skor", "" + skorAkhir);
		isiTeks("txt_waktu", formatMMSS(waktuTerpakai));
		
		if (tGagal) {
		    console.log("[GAMEOVER] txt_gagal ->", { teks: tGagal.text, warna: tGagal.color, font: tGagal.font,
		        x: tGagal.x, y: tGagal.y, skala: tGagal.scaleX, lebarBaris: tGagal.lineWidth });
		}
		
		// ==========================================
		// 6. TOMBOL
		// ==========================================
		pasang(root.btn_home, function() {
		    window.resetGameOver();
		    root.gotoAndStop("home");
		});
		
		pasang(root.btn_ulangi, function() {
		    window.resetGameOver();
		    root.gotoAndStop("inGame1");
		});
		
		// ==========================================
		// 7. MAINKAN SUARA
		// ==========================================
		window.mainkanSuaraGameOver();
	}

